async function saveConfig(patch){const u=window.AKTIF_KULLANICI||AppStore?.get?.('session.user');if(!u?.admin)throw new Error('yetkisiz');const current=appConfig(),next={...current,...patch,id:'uygulama',guncellenmeTarihi:new Date().toISOString()};if(patch.modules)next.modules=mergeRows(MODULE_DEFAULTS,patch.modules);if(patch.dashboardCards)next.dashboardCards=mergeRows(DASHBOARD_DEFAULTS,patch.dashboardCards);await DeviceData.set('appConfig',COL.navDuzeni,'uygulama',next,{merge:false});applyNavigation();window.dispatchEvent(new CustomEvent('koruk:app-config-changed',{detail:next}));return next}
