const TeacherListBuilder=(()=>{
  const TYPE='personelOgretmenListeleri';
  const clone=v=>{try{return structuredClone(v)}catch(_){return JSON.parse(JSON.stringify(v))}};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rows=t=>{const v=AppStore?.data?.(t);return Array.isArray(v)?v:[]};
  const user=()=>window.AKTIF_KULLANICI||AppStore?.get?.('session.user')||{};
  const uid=()=>String(user().uid||'').trim();
  const recordId=()=>`personnel_teacher_list_${uid()}`.replace(/[^\w-]/g,'_');
  const teacherName=t=>`${t?.ad||''} ${t?.soyad||''}`.replace(/\s+/g,' ').trim()||t?.adSoyad||'Öğretmen';
  const teachers=()=>rows('ogretmenler').filter(x=>x?.id).slice().sort((a,b)=>teacherName(a).localeCompare(teacherName(b),'tr',{sensitivity:'base'}));
  const defaultColumns=()=>[
    {key:'siraNo',label:'Sıra No',visible:true,width:64,align:'center'},
    {key:'adSoyad',label:'Ad Soyad',visible:true,width:190,align:'left'},
    {key:'brans',label:'Branş',visible:true,width:150,align:'left'},
    {key:'unvan',label:'Ünvan',visible:true,width:120,align:'left'},
    {key:'telefon',label:'Telefon',visible:false,width:120,align:'center'},
    {key:'eposta',label:'E-posta',visible:false,width:170,align:'left'},
    {key:'sorumluSinif',label:'Sorumlu Sınıf',visible:false,width:110,align:'center'},
    {key:'dereceKademe',label:'Derece / Kademe',visible:false,width:110,align:'center'},
    {key:'notlar',label:'Açıklama',visible:false,width:160,align:'left'},
    {key:'imza',label:'İmza',visible:true,width:120,align:'center'}
  ];
  function schoolDefaults(){const o=rows('okulBilgileri').find(x=>x.id==='ayarlar')||rows('okulBilgileri')[0]||window.okulBilgileriAyari||{},y=new Date().getFullYear();return{title:o.okulAdi||o.ad||'KORUK ORTAOKULU',subtitle:`${y}-${y+1} EĞİTİM ÖĞRETİM YILI`,reportTitle:'ÖĞRETMEN LİSTESİ',date:new Date().toISOString().slice(0,10),orientation:'landscape',logo:true,showDate:true,showTotal:true,leftFooter:'Hazırlayan\nMüdür Yardımcısı',rightFooter:'Onay\nOkul Müdürü'}}
  function blank(){return{listName:'Öğretmen Listesi',search:'',branch:'',sort:'name',selectedIds:teachers().map(x=>String(x.id)),title:schoolDefaults(),columns:defaultColumns(),customValues:{},blankRows:[],templates:[],savedLists:[]}}
  let root=null,state=blank(),preparedFor='',persistTimer=null;
  function branches(){return [...new Set(teachers().map(x=>String(x.brans||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'))}
  function selectedTeachers(){const map=new Map(teachers().map(x=>[String(x.id),x])),out=state.selectedIds.map(id=>map.get(String(id))).filter(Boolean);out.sort((a,b)=>state.sort==='branch'?String(a.brans||'').localeCompare(String(b.brans||''),'tr')||teacherName(a).localeCompare(teacherName(b),'tr'):state.sort==='title'?String(a.unvan||a.gorev||'').localeCompare(String(b.unvan||b.gorev||''),'tr')||teacherName(a).localeCompare(teacherName(b),'tr'):teacherName(a).localeCompare(teacherName(b),'tr'));return out}
  function filteredTeachers(){const q=String(state.search||'').toLocaleLowerCase('tr').trim();return teachers().filter(t=>(!state.branch||String(t.brans||'')===state.branch)&&(!q||`${teacherName(t)} ${t.brans||''} ${t.unvan||t.gorev||''}`.toLocaleLowerCase('tr').includes(q)))}
  const activeColumns=()=>state.columns.filter(c=>c.visible);
  const manualRows=()=>Array.isArray(state.blankRows)?state.blankRows:[];
  function cellValue(t,c,i){if(c.key==='siraNo')return i+1;if(c.key==='adSoyad')return teacherName(t);if(c.key==='brans')return t.brans||'';if(c.key==='unvan')return t.unvan||t.gorev||t.gorevi||'';if(c.key==='telefon')return t.telefon||t.telefon1||'';if(c.key==='eposta')return t.eposta||t.email||'';if(c.key==='sorumluSinif')return t.sorumluSinif||t.sinif||t.sinifAdi||'';if(c.key==='dereceKademe')return[t.derece,t.kademe].filter(v=>v!==null&&v!==undefined&&v!=='').join('/');if(c.key==='notlar')return t.notlar||t.not||'';if(c.key==='imza')return'';if(c.custom)return state.customValues?.[String(t.id)]?.[c.key]||'';return t[c.key]??''}
  const manualCell=(r,c)=>String(r?.values?.[c.key]??'');
  const totalRows=()=>selectedTeachers().length+manualRows().length;
  function fmtDate(v){if(!v)return'';const d=new Date(v+'T00:00:00');return Number.isNaN(d.getTime())?v:d.toLocaleDateString('tr-TR')}
  async function prepare(){const id=uid(),collection=COL?.ogretmenListeKayit;if(!id||!collection||!window.SyncEngine||!window.DeviceData)return false;if(preparedFor===id)return true;preparedFor=id;SyncEngine.register(TYPE,collection,{query:q=>q.where('sahipUid','==',id)});await SyncEngine.localHydrate([TYPE]);SyncEngine.schedule(80);return true}
  function loadState(){const d=blank(),rec=DeviceData?.list?.(TYPE)?.find?.(x=>x.id===recordId()&&x.sahipUid===uid()),s=rec?.state&&typeof rec.state==='object'?rec.state:{};state=rec?{...d,...clone(s),title:{...d.title,...clone(s.title||{})},columns:Array.isArray(s.columns)&&s.columns.length?clone(s.columns):d.columns,selectedIds:Array.isArray(s.selectedIds)?s.selectedIds.map(String):d.selectedIds,customValues:clone(s.customValues||{}),blankRows:Array.isArray(s.blankRows)?clone(s.blankRows):[],templates:Array.isArray(s.templates)?clone(s.templates):[],savedLists:Array.isArray(s.savedLists)?clone(s.savedLists):[]}:d;return state}
  function persist(){const id=uid(),collection=COL?.ogretmenListeKayit;if(!id||!collection||!DeviceData)return Promise.resolve(false);return DeviceData.set(TYPE,collection,recordId(),{scope:'personnel-teacher-list-builder',sahipUid:id,state:clone(state),guncellenme:new Date().toISOString()},{merge:false}).catch(e=>{console.warn('[TeacherListBuilder]',e?.message||e);return false})}
  function persistSoon(){clearTimeout(persistTimer);persistTimer=setTimeout(()=>void persist(),220)}
  function reportTable(editable=false){const cols=activeColumns(),list=selectedTeachers(),teacherHtml=list.map((t,i)=>`<tr>${cols.map(c=>`<td>${editable&&c.custom?`<input class="ka-input" data-tl-custom="${esc(t.id)}" data-key="${esc(c.key)}" value="${esc(cellValue(t,c,i))}">`:esc(cellValue(t,c,i))}</td>`).join('')}</tr>`).join(''),manualHtml=manualRows().map(r=>`<tr>${cols.map(c=>`<td>${editable?`<input class="ka-input" data-tl-manual="${esc(r.id)}" data-key="${esc(c.key)}" value="${esc(manualCell(r,c))}" placeholder="Yazın…">`:esc(manualCell(r,c))}</td>`).join('')}</tr>`).join('');return `<div class="ka-table-wrap"><table class="ka-table"><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${teacherHtml}${manualHtml}</tbody></table></div>`}
  function preview(){const h=state.title,manual=manualRows();return `<article class="ka-card"><div class="ka-card__header ka-row ka-row--between"><div><strong>4. Önizleme</strong><div class="ka-muted">${h.orientation==='landscape'?'Yatay':'Dikey'} A4 · ${selectedTeachers().length} öğretmen · ${manual.length} boş satır</div></div><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-tl-excel>Excel</button></div><div class="ka-card__body ka-stack"><div align="center"><strong>${esc(h.reportTitle)}</strong><div class="ka-muted">${esc(h.title)}</div><div class="ka-muted">${esc(h.subtitle)}</div></div>${h.showDate?`<div class="ka-muted">${esc(fmtDate(h.date))}</div>`:''}${reportTable(true)}${manual.length?`<div class="ka-row">${manual.map((r,i)=>`<button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-tl-delete-row="${esc(r.id)}">${i+1}. boş satırı sil</button>`).join('')}</div>`:''}${h.showTotal?`<div class="ka-muted">Toplam satır: ${totalRows()}</div>`:''}<div class="ka-grid"><div>${esc(h.leftFooter).replace(/\n/g,'<br>')}</div><div>${esc(h.rightFooter).replace(/\n/g,'<br>')}</div></div></div></article>`}
  function savedBlock(){const lists=state.savedLists||[],tpls=state.templates||[];if(!lists.length&&!tpls.length)return'';return `<details class="ka-card"><summary class="ka-card__body"><strong>Kayıtlı Listeler ve Şablonlar</strong></summary><div class="ka-card__body ka-stack">${lists.map(x=>`<div class="ka-row"><span class="ka-grow"><strong>${esc(x.name)}</strong><small class="ka-muted">${esc(x.savedAt||'')}</small></span><button class="ka-btn ka-btn--secondary ka-btn--sm" data-tl-open-list="${esc(x.id)}">Aç</button><button class="ka-btn ka-btn--ghost ka-btn--sm" data-tl-del-list="${esc(x.id)}">Sil</button></div>`).join('')}${tpls.length?`<strong>Şablonlar</strong>${tpls.map(x=>`<div class="ka-row"><span class="ka-grow">${esc(x.name)}</span><button class="ka-btn ka-btn--secondary ka-btn--sm" data-tl-open-template="${esc(x.id)}">Uygula</button><button class="ka-btn ka-btn--ghost ka-btn--sm" data-tl-del-template="${esc(x.id)}">Sil</button></div>`).join('')}`:''}</div></details>`}
  function teacherStep(){const chosen=new Set(state.selectedIds.map(String)),list=filteredTeachers();return `<details class="ka-card" open><summary class="ka-card__body"><strong>1. Öğretmenler ve Satırlar</strong> <span class="ka-muted">· ${chosen.size} öğretmen · ${manualRows().length} boş satır</span></summary><div class="ka-card__body ka-stack"><input class="ka-input" data-tl-search type="search" placeholder="Öğretmen ara…" value="${esc(state.search)}"><label class="ka-field"><span class="ka-field__label">Branş</span><select data-tl-branch><option value="">Tüm branşlar</option>${branches().map(b=>`<option value="${esc(b)}" ${state.branch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label class="ka-field"><span class="ka-field__label">Sıralama</span><select data-tl-sort><option value="name" ${state.sort==='name'?'selected':''}>Ada göre</option><option value="branch" ${state.sort==='branch'?'selected':''}>Branşa göre</option><option value="title" ${state.sort==='title'?'selected':''}>Ünvana göre</option></select></label><div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" data-tl-all type="button">Tümünü Seç</button><button class="ka-btn ka-btn--ghost ka-btn--sm" data-tl-none type="button">Temizle</button><button class="ka-btn ka-btn--secondary ka-btn--sm" data-tl-add-row type="button">+ Boş Satır Ekle</button></div><div class="ka-stack" data-tl-teacher-list>${list.map(t=>`<label class="ka-card ka-list-card" data-tl-teacher-row data-search-text="${esc(`${teacherName(t)} ${t.brans||''} ${t.unvan||t.gorev||''}`.toLocaleLowerCase('tr'))}"><div class="ka-card__body ka-row"><input type="checkbox" data-tl-teacher="${esc(t.id)}" ${chosen.has(String(t.id))?'checked':''}><span class="ka-grow"><strong>${esc(teacherName(t))}</strong><small class="ka-muted">${esc(t.brans||'Branş belirtilmemiş')} · ${esc(t.unvan||t.gorev||'Öğretmen')}</small></span></div></label>`).join('')||'<div class="ka-empty">Öğretmen bulunamadı.</div>'}</div></div></details>`}
  function headerStep(){const h=state.title;return `<details class="ka-card"><summary class="ka-card__body"><strong>2. Başlık ve Sayfa</strong></summary><div class="ka-card__body ka-stack"><label class="ka-field"><span class="ka-field__label">Liste Adı</span><input class="ka-input" data-tl-list-name value="${esc(state.listName)}"></label><label class="ka-field"><span class="ka-field__label">Okul Adı</span><input class="ka-input" data-tl-head="title" value="${esc(h.title)}"></label><label class="ka-field"><span class="ka-field__label">Alt Başlık</span><input class="ka-input" data-tl-head="subtitle" value="${esc(h.subtitle)}"></label><label class="ka-field"><span class="ka-field__label">Rapor Başlığı</span><input class="ka-input" data-tl-head="reportTitle" value="${esc(h.reportTitle)}"></label><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Sayfa Yönü</span><select data-tl-head="orientation"><option value="portrait" ${h.orientation==='portrait'?'selected':''}>Dikey A4</option><option value="landscape" ${h.orientation==='landscape'?'selected':''}>Yatay A4</option></select></label><label class="ka-field"><span class="ka-field__label">Tarih</span><input class="ka-input" type="date" data-tl-head="date" value="${esc(h.date)}"></label></div><div class="ka-row"><label><input type="checkbox" data-tl-flag="logo" ${h.logo?'checked':''}> Logo</label><label><input type="checkbox" data-tl-flag="showDate" ${h.showDate?'checked':''}> Tarih</label><label><input type="checkbox" data-tl-flag="showTotal" ${h.showTotal?'checked':''}> Toplam</label></div><label class="ka-field"><span class="ka-field__label">Sol İmza Alanı</span><textarea data-tl-head="leftFooter">${esc(h.leftFooter)}</textarea></label><label class="ka-field"><span class="ka-field__label">Sağ İmza Alanı</span><textarea data-tl-head="rightFooter">${esc(h.rightFooter)}</textarea></label></div></details>`}
  function columnStep(){return `<details class="ka-card"><summary class="ka-card__body"><strong>3. Sütunlar</strong> <span class="ka-muted">· ${activeColumns().length} görünür</span></summary><div class="ka-card__body ka-stack"><button class="ka-btn ka-btn--secondary" type="button" data-tl-add-column>+ Özel Sütun Ekle</button>${state.columns.map((c,i)=>`<article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row"><label class="ka-grow"><input type="checkbox" data-tl-visible="${esc(c.key)}" ${c.visible?'checked':''}> <strong>${esc(c.label)}</strong></label><button class="ka-icon-button" type="button" data-tl-up="${esc(c.key)}" ${i===0?'disabled':''}>↑</button><button class="ka-icon-button" type="button" data-tl-down="${esc(c.key)}" ${i===state.columns.length-1?'disabled':''}>↓</button>${c.custom?`<button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-tl-delete-column="${esc(c.key)}">Sil</button>`:''}</div><label class="ka-field"><span class="ka-field__label">Sütun Başlığı</span><input class="ka-input" data-tl-label="${esc(c.key)}" value="${esc(c.label)}"></label><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Genişlik</span><input class="ka-input" type="number" min="45" max="360" data-tl-width="${esc(c.key)}" value="${Number(c.width)||100}"></label><label class="ka-field"><span class="ka-field__label">Hizalama</span><select data-tl-align="${esc(c.key)}"><option value="left" ${c.align==='left'?'selected':''}>Sol</option><option value="center" ${c.align==='center'?'selected':''}>Orta</option><option value="right" ${c.align==='right'?'selected':''}>Sağ</option></select></label></div></div></article>`).join('')}</div></details>`}
  function page(){return `<section class="ka-page ka-stack" data-central-teacher-list><article class="ka-card"><div class="ka-card__body ka-stack"><small>PERSONEL İŞLERİ</small><h2>Öğretmen Liste Oluşturucu</h2><p class="ka-muted">Mobil öncelikli liste tasarım ekranı. Öğretmen seçebilir veya istediğiniz içeriği yazabileceğiniz boş satırlar ekleyebilirsiniz.</p><div class="ka-grid"><button class="ka-btn ka-btn--secondary" type="button" data-tl-template-save>Şablon Kaydet</button><button class="ka-btn ka-btn--secondary" type="button" data-tl-list-save>Listeyi Kaydet</button><button class="ka-btn" type="button" data-tl-report>Rapor Oluştur</button><button class="ka-btn ka-btn--secondary" type="button" data-tl-reset>Yeni Liste</button></div></div></article>${teacherStep()}${headerStep()}${columnStep()}${preview()}${savedBlock()}</section>`}
  function moveColumn(key,delta){const i=state.columns.findIndex(c=>c.key===key),j=i+delta;if(i<0||j<0||j>=state.columns.length)return;[state.columns[i],state.columns[j]]=[state.columns[j],state.columns[i]];persistSoon();render()}
  function saveList(){const snap=clone({...state,savedLists:[],templates:[]});state.savedLists=[{id:'list_'+Date.now().toString(36),name:state.listName||'Öğretmen Listesi',savedAt:new Date().toLocaleString('tr-TR'),snapshot:snap},...(state.savedLists||[])].slice(0,30);persistSoon();render();window.toast?.('Öğretmen listesi kaydedildi.')}
  function saveTemplate(){const n=prompt('Şablon adı:',state.listName||'Öğretmen Listesi');if(!n?.trim())return;state.templates=[{id:'tpl_'+Date.now().toString(36),name:n.trim(),snapshot:{title:clone(state.title),columns:clone(state.columns),sort:state.sort}},...(state.templates||[])].slice(0,20);persistSoon();render();window.toast?.('Şablon kaydedildi.')}
  function reportBody(){const h=state.title,list=selectedTeachers(),manual=manualRows(),cols=activeColumns(),heads=cols.map(c=>`<th>${esc(c.label)}</th>`).join(''),teacherBody=list.map((t,i)=>`<tr>${cols.map(c=>`<td>${esc(cellValue(t,c,i))}</td>`).join('')}</tr>`).join(''),manualBody=manual.map(r=>`<tr>${cols.map(c=>`<td>${esc(manualCell(r,c))}</td>`).join('')}</tr>`).join('');return `${h.showDate?`<div align="right">${esc(fmtDate(h.date))}</div>`:''}<table><thead><tr>${heads}</tr></thead><tbody>${teacherBody}${manualBody}</tbody></table>${h.showTotal?`<p>Toplam satır: <strong>${totalRows()}</strong></p>`:''}<div>${esc(h.leftFooter).replace(/\n/g,'<br>')}</div><div>${esc(h.rightFooter).replace(/\n/g,'<br>')}</div>`}
  async function report(){if(!totalRows())return window.toast?.('En az bir öğretmen seçin veya boş satır ekleyin.');if(!window.ReportEngine?.printReport)await loadScript('js/modules/report-engine.js');return window.ReportEngine.printReport(state.title.reportTitle||state.listName,reportBody(),{fileName:state.listName||'Ogretmen_Listesi',yon:state.title.orientation==='landscape'?'yatay':'dikey',logoGoster:!!state.title.logo,baslikGoster:true,tarihGoster:false,ustBaslik:state.title.subtitle,okulAdi:state.title.title,extraHead:'<style>.ka-report-headcopy{text-align:center;align-items:center}</style>'})}
  async function exportExcel(){if(!totalRows())return window.toast?.('En az bir öğretmen seçin veya boş satır ekleyin.');if(!window.ExcelJS)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.4.0/exceljs.min.js');if(!window.ExcelJS)throw new Error('Excel bileşeni yüklenemedi.');const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('Öğretmen Listesi'),cols=activeColumns(),list=selectedTeachers();ws.addRow(cols.map(c=>c.label));list.forEach((t,i)=>ws.addRow(cols.map(c=>cellValue(t,c,i))));manualRows().forEach(r=>ws.addRow(cols.map(c=>manualCell(r,c))));ws.getRow(1).font={bold:true};ws.columns=cols.map(c=>({width:Math.max(8,Math.round((Number(c.width)||100)/7))}));const buf=await wb.xlsx.writeBuffer(),blob=new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),file=(state.listName||'Ogretmen_Listesi').replace(/[\\/:*?"<>|]+/g,'_')+'.xlsx';if(typeof window.uygulamaDosyaKaydet==='function')return window.uygulamaDosyaKaydet(blob,file);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
  function render(){if(!root)return;root.innerHTML=page();bind();window.PermissionService?.apply?.(root)}
  function bind(){if(!root)return;const search=root.querySelector('[data-tl-search]');search?.addEventListener('input',e=>{state.search=e.target.value;persistSoon();const q=state.search.toLocaleLowerCase('tr').trim();root.querySelectorAll('[data-tl-teacher-row]').forEach(row=>row.hidden=!!q&&!String(row.dataset.searchText||'').includes(q))});root.querySelector('[data-tl-branch]')?.addEventListener('change',e=>{state.branch=e.target.value;state.search='';persistSoon();render()});root.querySelector('[data-tl-sort]')?.addEventListener('change',e=>{state.sort=e.target.value;persistSoon();render()});root.querySelectorAll('[data-tl-teacher]').forEach(el=>el.onchange=()=>{const id=String(el.dataset.tlTeacher);state.selectedIds=el.checked?[...new Set([...state.selectedIds.map(String),id])]:state.selectedIds.map(String).filter(x=>x!==id);persistSoon();render()});root.querySelector('[data-tl-all]')?.addEventListener('click',()=>{state.selectedIds=filteredTeachers().map(x=>String(x.id));persistSoon();render()});root.querySelector('[data-tl-none]')?.addEventListener('click',()=>{state.selectedIds=[];persistSoon();render()});root.querySelector('[data-tl-add-row]')?.addEventListener('click',()=>{state.blankRows=[...manualRows(),{id:'row_'+Date.now().toString(36),values:{}}];persistSoon();render()});root.querySelectorAll('[data-tl-delete-row]').forEach(b=>b.onclick=()=>{state.blankRows=manualRows().filter(r=>r.id!==b.dataset.tlDeleteRow);persistSoon();render()});root.querySelectorAll('[data-tl-manual]').forEach(el=>el.oninput=()=>{const row=manualRows().find(r=>r.id===el.dataset.tlManual);if(!row)return;row.values??={};row.values[el.dataset.key]=el.value;persistSoon()});root.querySelector('[data-tl-list-name]')?.addEventListener('input',e=>{state.listName=e.target.value;persistSoon()});root.querySelectorAll('[data-tl-head]').forEach(el=>el.onchange=()=>{state.title[el.dataset.tlHead]=el.value;persistSoon();render()});root.querySelectorAll('[data-tl-flag]').forEach(el=>el.onchange=()=>{state.title[el.dataset.tlFlag]=el.checked;persistSoon();render()});root.querySelectorAll('[data-tl-visible]').forEach(el=>el.onchange=()=>{const c=state.columns.find(x=>x.key===el.dataset.tlVisible);if(c)c.visible=el.checked;persistSoon();render()});root.querySelectorAll('[data-tl-label]').forEach(el=>el.onchange=()=>{const c=state.columns.find(x=>x.key===el.dataset.tlLabel);if(c)c.label=el.value.trim()||c.label;persistSoon();render()});root.querySelectorAll('[data-tl-width]').forEach(el=>el.onchange=()=>{const c=state.columns.find(x=>x.key===el.dataset.tlWidth);if(c)c.width=Math.max(45,Math.min(360,Number(el.value)||100));persistSoon();render()});root.querySelectorAll('[data-tl-align]').forEach(el=>el.onchange=()=>{const c=state.columns.find(x=>x.key===el.dataset.tlAlign);if(c)c.align=el.value;persistSoon();render()});root.querySelectorAll('[data-tl-up]').forEach(b=>b.onclick=()=>moveColumn(b.dataset.tlUp,-1));root.querySelectorAll('[data-tl-down]').forEach(b=>b.onclick=()=>moveColumn(b.dataset.tlDown,1));root.querySelector('[data-tl-add-column]')?.addEventListener('click',()=>{const n=prompt('Yeni sütun başlığı:','Açıklama');if(!n?.trim())return;state.columns.push({key:'custom_'+Date.now().toString(36),label:n.trim(),visible:true,width:140,align:'left',custom:true});persistSoon();render()});root.querySelectorAll('[data-tl-delete-column]').forEach(b=>b.onclick=()=>{state.columns=state.columns.filter(c=>c.key!==b.dataset.tlDeleteColumn);persistSoon();render()});root.querySelectorAll('[data-tl-custom]').forEach(el=>el.oninput=()=>{const id=String(el.dataset.tlCustom);state.customValues[id]??={};state.customValues[id][el.dataset.key]=el.value;persistSoon()});root.querySelector('[data-tl-template-save]')?.addEventListener('click',saveTemplate);root.querySelector('[data-tl-list-save]')?.addEventListener('click',saveList);root.querySelectorAll('[data-tl-report]').forEach(b=>b.onclick=report);root.querySelector('[data-tl-excel]')?.addEventListener('click',exportExcel);root.querySelector('[data-tl-reset]')?.addEventListener('click',()=>{if(!confirm('Yeni liste başlatılsın mı?'))return;const lists=state.savedLists,tpls=state.templates;state=blank();state.savedLists=lists;state.templates=tpls;persistSoon();render()});root.querySelectorAll('[data-tl-open-list]').forEach(b=>b.onclick=()=>{const x=state.savedLists.find(v=>v.id===b.dataset.tlOpenList);if(!x)return;const lists=state.savedLists,tpls=state.templates;state={...blank(),...clone(x.snapshot),blankRows:Array.isArray(x.snapshot?.blankRows)?clone(x.snapshot.blankRows):[],savedLists:lists,templates:tpls};persistSoon();render()});root.querySelectorAll('[data-tl-del-list]').forEach(b=>b.onclick=()=>{state.savedLists=state.savedLists.filter(v=>v.id!==b.dataset.tlDelList);persistSoon();render()});root.querySelectorAll('[data-tl-open-template]').forEach(b=>b.onclick=()=>{const x=state.templates.find(v=>v.id===b.dataset.tlOpenTemplate);if(!x)return;state.title={...state.title,...clone(x.snapshot.title||{})};state.columns=clone(x.snapshot.columns||state.columns);state.sort=x.snapshot.sort||state.sort;persistSoon();render()});root.querySelectorAll('[data-tl-del-template]').forEach(b=>b.onclick=()=>{state.templates=state.templates.filter(v=>v.id!==b.dataset.tlDelTemplate);persistSoon();render()})}
  async function open(target){root=target||document.getElementById('v2ModuleRoot');if(!root)return false;await prepare();loadState();render();return true}
  function close(){clearTimeout(persistTimer);root=null;return true}
  return{open,close,render,report,exportExcel};
})();
window.CentralTeacherListBuilder=TeacherListBuilder;

function registerClassicPageRoutes(){
  if(typeof window.ShellUI?.registerPageRoute!=='function')return false;
  const diplomaRoute=type=>async({root})=>{window.ManagementModule?.unmount?.();if(!window.ReportEngine?.printReport)await loadScript('js/modules/report-engine.js');if(!window.PersonnelDocuments?.open)await loadScript('js/modules/personnel-documents.js');if(!window.PersonnelDocuments?.open)throw new Error('personnel-documents-load');return window.PersonnelDocuments.open(type,root)};
  const meetingRoute=async({root})=>{window.ManagementModule?.unmount?.();if(!window.ReportEngine?.printReport)await loadScript('js/modules/report-engine.js');if(!window.MeetingSchedulePage?.open)await loadScript('js/modules/meeting-schedule.js');if(!window.MeetingSchedulePage?.open)throw new Error('meeting-schedule-load');return window.MeetingSchedulePage.open(root)};
  const teacherListRoute=async({root})=>{window.ManagementModule?.unmount?.();if(!window.ReportEngine?.printReport)await loadScript('js/modules/report-engine.js');return TeacherListBuilder.open(root)};
  window.ShellUI.registerPageRoute('diploma-request',diplomaRoute('request'));
  window.ShellUI.registerPageRoute('diploma-response',diplomaRoute('response'));
  window.ShellUI.registerPageRoute('meeting-schedule',meetingRoute);
  window.ShellUI.registerPageRoute('teacher-list-builder',teacherListRoute);
  return true;
}
registerClassicPageRoutes();

