function moduleLevel(name){const direct=rawPermissionLevel('module.'+name),{user,role}=permissionSession();if(name==='transport'&&user?.uid&&user?.admin!==true&&(user?.bagliOgretmenId||user?.ogretmenId))return'read';if(direct)return direct;if(name==='dashboard'&&user?.uid)return'read';return role?.yetkiler&&Object.keys(role.yetkiler).length?'hidden':'edit'}
